#!/usr/bin/env python3

"""
========================================================
RoboMaster 哨兵机器人
第15课：模拟激光雷达
========================================================

本程序模拟一个二维激光雷达。

程序的工作流程：

    创建 LaserScan
          ↓
    模拟 360° 雷达数据
          ↓
    发布到 /scan

真实机器人以后会变成：

    真实激光雷达
          ↓
       雷达驱动
          ↓
         /scan

因此本课的主要目的不是学习 Python，
而是理解 ROS2 中激光雷达数据是怎么进入系统的。
========================================================
"""


# ========================================================
# 1. 导入 ROS2
# ========================================================

import rclpy

from rclpy.node import Node


# ========================================================
# 2. 导入 LaserScan 消息类型
# ========================================================

from sensor_msgs.msg import LaserScan


# ========================================================
# 3. 导入数学库
# ========================================================

import math


# ========================================================
# 4. 创建雷达节点
# ========================================================

class ScanPublisher(Node):

    """
    模拟激光雷达的 ROS2 节点。

    发布：

        /scan

    消息类型：

        sensor_msgs/msg/LaserScan
    """

    def __init__(self):

        # ------------------------------------------------
        # 创建 ROS2 节点
        # ------------------------------------------------

        super().__init__(
            "lesson15_scan_publisher"
        )


        # ------------------------------------------------
        # 创建 Publisher
        # ------------------------------------------------

        self.publisher = self.create_publisher(

            LaserScan,

            "/scan",

            10
        )


        # ------------------------------------------------
        # 创建定时器
        # ------------------------------------------------

        # 每 0.1 秒执行一次 publish_scan()

        self.timer = self.create_timer(

            0.1,

            self.publish_scan
        )


        # ------------------------------------------------
        # 输出启动信息
        # ------------------------------------------------

        self.get_logger().info(

            "第15课：模拟激光雷达已经启动"
        )


    # ====================================================
    # 发布雷达数据
    # ====================================================

    def publish_scan(self):

        """
        创建一帧 LaserScan 数据并发布。
        """


        # ------------------------------------------------
        # 创建 LaserScan 消息
        # ------------------------------------------------

        scan = LaserScan()


        # ------------------------------------------------
        # 设置时间戳
        # ------------------------------------------------

        scan.header.stamp = (

            self.get_clock()
            .now()
            .to_msg()
        )


        # ------------------------------------------------
        # 设置坐标系
        # ------------------------------------------------

        # 说明：

        # 当前雷达数据属于 laser 坐标系

        scan.header.frame_id = "laser"


        # =================================================
        # 设置扫描角度
        # =================================================

        # 从 -180° 开始

        scan.angle_min = -math.pi


        # 到 +180°

        scan.angle_max = math.pi


        # 每一个雷达数据间隔 1°

        scan.angle_increment = math.radians(1.0)


        # =================================================
        # 设置雷达测距范围
        # =================================================

        # 最小测量距离：

        scan.range_min = 0.1


        # 最大测量距离：

        scan.range_max = 10.0


        # =================================================
        # 创建距离数组
        # =================================================

        ranges = []


        # =================================================
        # 模拟 360 个方向
        # =================================================

        for i in range(360):

            # ------------------------------------------------
            # 默认距离
            # ------------------------------------------------

            # 假设周围没有障碍物，
            # 那么我们让雷达检测到 5 米。

            distance = 5.0


            # ------------------------------------------------
            # 模拟正前方障碍物
            # ------------------------------------------------

            # 我们规定：
            #
            # i = 180
            #
            # 对应机器人正前方 0°。
            #
            # 因此：
            #
            # i = 175 → -5°
            # i = 180 →  0°
            # i = 185 → +5°
            #
            # 让这个范围内出现一个障碍物。

            if i == 180:

                # 障碍物距离机器人 2 米

                distance = 0.5


            # ------------------------------------------------
            # 把距离加入数组
            # ------------------------------------------------

            ranges.append(distance)


        # =================================================
        # 把距离数组写入 LaserScan
        # =================================================

        scan.ranges = ranges


        # =================================================
        # 发布 LaserScan
        # =================================================

        self.publisher.publish(scan)


# ========================================================
# 5. main 函数
# ========================================================

def main(args=None):

    # ----------------------------------------------------
    # 初始化 ROS2
    # ----------------------------------------------------

    rclpy.init(args=args)


    # ----------------------------------------------------
    # 创建节点
    # ----------------------------------------------------

    node = ScanPublisher()


    try:

        # ------------------------------------------------
        # 让节点持续运行
        # ------------------------------------------------

        rclpy.spin(node)


    except KeyboardInterrupt:

        pass


    # ----------------------------------------------------
    # 程序结束时销毁节点
    # ----------------------------------------------------

    node.destroy_node()


    # ----------------------------------------------------
    # 关闭 ROS2
    # ----------------------------------------------------

    rclpy.shutdown()


# ========================================================
# 6. 程序入口
# ========================================================

if __name__ == "__main__":

    main()